export function translateInterface(value: string): string {
  const leading = value.match(/^\s*/)?.[0] ?? '';
  const trailing = value.match(/\s*$/)?.[0] ?? '';
  const core = value.trim();
  if (!/[А-Яа-яЁё]/.test(core)) return value;
  const normalized = core.replace(/\s+/g, ' ');
  const exact = TEXT[core] || TEXT[normalized] || MANAGERS.find(manager => manager.name === normalized)?.nameEn;
  if (exact) return leading + exact + trailing;
  const matchOpponent = normalized.match(/^(.+) \((д|в)\)$/);
  if (matchOpponent) return `${leading}${TEXT[matchOpponent[1]] ?? matchOpponent[1]} (${matchOpponent[2] === 'д' ? 'H' : 'A'})${trailing}`;
  const patterns: Array<[RegExp, string]> = [
    [/^ТУР (\d+) \/ (\d+)$/, 'MATCHWEEK $1 / $2'],
    [/^🏅 (\d+)\/(\d+) трофеев$/, '🏅 $1/$2 trophies'],
    [/^(.+) \(д\)$/, '$1 (H)'],
    [/^(.+) \(в\)$/, '$1 (A)'],
    [/^Играть с (.+) — бонус к рейтингу команды$/, 'Play with $1 — team rating bonus'],
    [/^(\d+) тренеров доступны$/, '$1 managers available'],
    [/^(\d+) поз\. осталось$/, '$1 positions left'],
    [/^(\d+) сезонов · (\d+) игроков$/, '$1 seasons · $2 players'],
    [/^(\d+) сезонов РПЛ · (\d+) игроков в базе \(2010–2021\)$/, '$1 RPL seasons · $2 players in the 2010–2021 database'],
    [/^⚽ Все матчи сезона · (\d+)$/, '⚽ All season matches · $1'],
    [/^Сезоны (\d+)–(\d+)$/, 'Seasons $1–$2'],
    [/^(\d+) мин назад$/, '$1 min ago'], [/^(\d+) ч назад$/, '$1 hr ago'], [/^(\d+) дн назад$/, '$1 days ago'],
    [/^Осталось (\d+) дн\. До удаления прогресс сохраняется\.$/, '$1 days left. Progress is retained until deletion.'],
    [/^Удаление профиля запланировано на (.+)\.$/, 'Profile deletion scheduled for $1.'],
    [/^(\d+) очков$/, '$1 points'],
    [/^(\d+) голов$/, '$1 goals'], [/^(\d+) передач$/, '$1 assists'], [/^(\d+) сэйвов$/, '$1 saves'],
    [/^(\d+)-е место · (\d+) очков · (\d+) побед$/, '$1th place · $2 points · $3 wins'],
    [/^(\d+)-е место$/, '$1th place'], [/^(\d+)-е$/, '$1th'],
    [/^очков · (\d+)-е место$/, 'points · $1th place'],
    [/^Забито (\d+)$/, 'Goals for $1'], [/^Пропущено (\d+)$/, 'Goals against $1'],
    [/^(\d+)\/11 заполнено$/, '$1/11 filled'],
    [/^📜 История \((\d+)\)$/, '📜 History ($1)'],
    [/^Шаг (\d+)$/, 'Step $1'],
    [/^Пустая позиция (.+)$/, 'Empty position $1'],
    [/^(.+) не может играть на (.+)$/, '$1 cannot play at $2'],
    [/^Нация «(.+)» не найдена$/, 'Nation “$1” not found'],
    [/^⭐ Средний рейтинг: (\d+)$/, '⭐ Average rating: $1'],
    [/^⚽ Голы: (\d+)–(\d+)$/, '⚽ Goals: $1–$2'],
    [/^🏆 Итог: (\d+)(?:-е)? место · (\d+) очков$/, '🏆 Result: $1th place · $2 points'],
    [/^🏆 (\d+) место · (\d+) очков$/, '🏆 $1th place · $2 points'],
    [/^✅ (\d+) побед · 🤝 (\d+) ничьих · ❌ (\d+) поражений$/, '✅ $1 wins · 🤝 $2 draws · ❌ $3 losses'],
    [/^🏟️ Клуб: (.+)$/, '🏟️ Club: $1'],
    [/^🏟️ Обычный драфт · (.+)$/, '🏟️ Classic draft · $1'],
    [/^Сезонов: (\d+) · Титулов: (\d+)$/, 'Seasons: $1 · Titles: $2'],
    [/^МОЙ КЛУБ · (.+)$/, 'MY CLUB · $1'],
    [/^\+?(\d+) к силе$/, '+$1 strength'],
    [/^(\d+)В$/, '$1W'], [/^(\d+)Н$/, '$1D'], [/^(\d+)П$/, '$1L'], [/^(\d+) побед$/, '$1 wins'], [/^(\d+) сухих$/, '$1 clean sheets'],
    [/^Схема заблокирована: (.+)$/, 'Formation locked: $1'],
    [/^Начать драфт · (.+)$/, 'Start draft · $1'],
    [/^Минимум (\d+) игр\.$/, 'At least $1 games.'],
    [/^(\d+) переброс\(а\)$/, '$1 rerolls'],
    [/^Слабое звено: (.+) ⚠️$/, 'Weak link: $1 ⚠️'],
    [/^Тренер: (.+)$/, 'Manager: $1'],
    [/^\+ (\d+) бонус тренера$/, '+ $1 manager bonus'],
  ];
  for (const [pattern, replacement] of patterns) {
    if (pattern.test(normalized)) return leading + localizeManagerNames(normalized.replace(pattern, replacement)).replace(/\b(\d+)th\b/g, (_, value: string) => {
      const n = Number(value);
      return `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : n % 10 === 1 ? 'st' : n % 10 === 2 ? 'nd' : n % 10 === 3 ? 'rd' : 'th'}`;
    }) + trailing;
  }
  return localizeManagerNames(value);
}

function localizeManagerNames(value: string): string {
  for (const manager of MANAGERS) value = value.replaceAll(manager.name, manager.nameEn);
  return value;
}

export function localizeShareText(value: string): string {
  if (typeof document === 'undefined' || document.documentElement.lang !== 'en') return value;
  return value.split('\n').map(line => {
    const exact = translateInterface(line);
    if (exact !== line) return exact;
    let result = line;
    for (const [source, target] of Object.entries(TEXT).sort((a, b) => b[0].length - a[0].length)) {
      if (source.length > 3 && result.includes(source)) result = result.replaceAll(source, target);
    }
    return result.replace('#30п0 #ФутбольныйДрафт', '#30to0 #FootballDraft');
  }).join('\n');
}
